message.content:
{
  "requirements": [
    {
      "id": "Q1",
      "question": "연구 결과가 적용되는 대상·자료·환경의 범위는 어디까지이며, 그 범위를 벗어나면 일반화에 어떤 제약이 생기는가?",
      "expected_fields": [
        "적용 범위의 구체적 대상·자료·조건",
        "범위를 벗어날 때 예상되는 일반화 제약",
        "범위 설정의 근거 또는 한계 인식"
      ],
      "priority": "required",
      "applies_when": null
    },
    {
      "id": "Q2",
      "question": "방법·구현·설정의 효율이나 배포·운용 측면의 최적화 가능성은 어디까지 검토되었는가?",
      "expected_fields": [
        "효율 또는 배포·운용 관련 검토 내용",
        "최적화 가능성의 범위",
        "검토하지 않았다면 그 이유와 해석상 한계"
      ],
      "priority": "required",
      "applies_when": null
    },
    {
      "id": "Q3",
      "question": "향후 연구 초점으로 제시된 방향은 무엇이며, 그것이 현재 결과의 어떤 공백·제약과 연결되는가?",
      "expected_fields": [
        "제시된 향후 연구 초점",
        "현재 결과의 공백·제약과의 연결",
        "초점이 실제 검증 가능한 방향인지 여부"
      ],
      "priority": "required",
      "applies_when": null
    },
    {
      "id": "Q4",
      "question": "평가·비교의 범위를 정한 대상 수, 워크로드, 소프트웨어 스택, 실행 조건 등은 무엇이며, 그 범위가 결과 해석에 어떤 제약을 주는가?",
      "expected_fields": [
        "대상 수·워크로드·소프트웨어 스택·실행 조건의 범위",
        "범위 설정 방식",
        "범위가 해석에 주는 제약"
      ],
      "priority": "required",
      "applies_when": "평가·비교의 범위를 대상 수, 워크로드, 소프트웨어 스택, 실행 조건 등으로 한정한 경우"
    },
    {
      "id": "Q5",
      "question": "기준선 또는 구성 요소 단위 비교에서 공정한 비교를 위해 의도적으로 제한한 최적화가 있는가? 있다면 무엇이며, 그 제한이 해석에 미치는 영향은 무엇인가?",
      "expected_fields": [
        "제한한 최적화의 내용",
        "제한한 이유",
        "제한으로 인한 해석상 영향 또는 한계"
      ],
      "priority": "required",
      "applies_when": "기준선 또는 구성 요소 단위 비교를 수행했고, 비교를 위해 최적화 일부를 제한한 경우"
    },
    {
      "id": "Q6",
      "question": "전체 처리 과정이나 복합 구성을 비교할 때 여러 요소가 동시에 바뀌어 개별 요소의 효과를 분리하기 어려운 점이 있는가? 있다면 그 한계는 어떻게 설명되는가?",
      "expected_fields": [
        "여러 요소가 동시에 바뀐 비교 여부",
        "개별 효과 분리가 어려운 지점",
        "한계에 대한 설명 또는 해석 방식"
      ],
      "priority": "required",
      "applies_when": "전체 처리 과정 또는 복합 구성을 비교해 여러 요소가 함께 바뀐 경우"
    },
    {
      "id": "Q7",
      "question": "호스트·플랫폼·실행 환경의 차이로 인해 절대 수치(예: 절대 지연 시간 등)의 해석에 제약이 있는가? 있다면 그 제약은 무엇인가?",
      "expected_fields": [
        "호스트·환경 차이로 인한 해석 제약",
        "절대 수치 해석에서 주의가 필요한 부분",
        "제약의 범위"
      ],
      "priority": "required",
      "applies_when": "호스트, 플랫폼, 실행 환경 등의 차이가 존재하고 절대 수치 해석이 포함된 경우"
    },
    {
      "id": "Q8",
      "question": "평가에서 제외한 지표가 있는가? 있다면 무엇을 왜 제외했으며, 그 제외가 결과 해석의 범위를 어떻게 제한하는가?",
      "expected_fields": [
        "제외한 지표",
        "제외 이유",
        "제외로 인한 해석 범위 제한"
      ],
      "priority": "required",
      "applies_when": "일부 지표를 평가에서 제외한 경우"
    },
    {
      "id": "Q9",
      "question": "결과가 실제로 의미하는 범위는 어디까지이며, 주장보다 더 넓게 해석하지 않기 위해 필요한 한계는 무엇인가?",
      "expected_fields": [
        "결과가 의미하는 범위",
        "주장 대비 해석의 한계",
        "과도한 일반화를 피하기 위한 조건"
      ],
      "priority": "required",
      "applies_when": null
    }
  ],
  "criterion_assignments": {
    "ref1_limitations_required_1": {
      "question_ids": ["Q1"],
      "reason": "데이터 범위와 일반화 제약은 적용 범위와 일반화 제약을 묻는 질문으로 확인한다."
    },
    "ref1_limitations_required_2": {
      "question_ids": ["Q2"],
      "reason": "모델 효율과 배포 최적화 가능성은 효율·배포·운용 측면의 검토 범위와 한계로 확인한다."
    },
    "ref1_limitations_required_3": {
      "question_ids": ["Q3"],
      "reason": "향후 연구 초점은 제시된 방향과 현재 결과의 공백·제약 연결로 확인한다."
    },
    "ref2_limitations_required_1": {
      "question_ids": ["Q4"],
      "reason": "대상 수·워크로드·소프트웨어 스택·실행 조건의 범위는 평가 범위 설정과 해석 제약으로 확인한다."
    },
    "ref2_limitations_required_2": {
      "question_ids": ["Q5"],
      "reason": "기준선과 구성 요소 단위 비교에서 통제하기 위해 제한한 최적화는 제한한 최적화와 그 영향으로 확인한다."
    },
    "ref2_limitations_required_3": {
      "question_ids": ["Q6"],
      "reason": "전체 처리 과정 비교에서 여러 요소가 동시에 바뀌어 개별 효과 분리가 어려운 점은 복합 비교의 분리 한계와 설명으로 확인한다."
    },
    "ref2_limitations_required_4": {
      "question_ids": ["Q7"],
      "reason": "호스트 차이로 인한 절대 지연 시간 해석의 제약은 환경 차이와 절대 수치 해석 제약으로 확인한다."
    },
    "ref2_limitations_required_5": {
      "question_ids": ["Q8"],
      "reason": "평가에서 제외한 지표와 그 이유 및 해석 범위는 제외 지표·이유·해석 범위 제한으로 확인한다."
    },
    "ref2_limitations_required_6": {
      "question_ids": ["Q9"],
      "reason": "결과가 의미하는 범위의 한계는 결과 의미 범위와 과도한 해석 방지 조건으로 확인한다."
    }
  }
}
